-- EXTRA TIME — Seed U19 Regionale 2026/2027 riformulato (Juniores U19 B, 6 gironi)
-- Fonte: U19 Regionale_Lazio.pdf. Sostituisce struttura precedente. Idempotente.

begin;

-- Pulizia U19 Regionale precedente (brochure pre-riforma) prima del reimport.
delete from matches where group_id in (
  select g.id from competition_groups g join competitions co on co.id=g.competition_id
    join seasons s on s.id=g.season_id and s.is_current where co.category='U19 Regionale');
delete from group_teams where group_id in (
  select g.id from competition_groups g join competitions co on co.id=g.competition_id
    join seasons s on s.id=g.season_id and s.is_current where co.category='U19 Regionale');

-- La stagione reale diventa quella corrente; le altre non lo sono più.
update seasons set is_current = false where is_current = true;

on conflict (id) do update set is_current = excluded.is_current;

-- Competizioni (una per categoria+livello)
on conflict (id) do nothing;

-- Gironi
on conflict (id) do nothing;

-- Club (84 società distinte)
on conflict (id) do nothing;

-- Squadre (club × categoria+livello)
on conflict (id) do nothing;

-- Iscrizioni squadra→girone
on conflict do nothing;

-- Calendario (partite programmate)
on conflict (id) do nothing;

commit;
